import struct, sys

ISO = "/app/alpine.iso"
SECTOR = 2048
f = open(ISO, "rb")

def read_at(off, n):
    f.seek(off)
    return f.read(n)

def parse_dr(data, off):
    if off >= len(data):
        return None
    dr_len = data[off]
    if dr_len == 0:
        return None
    lba = struct.unpack_from("<I", data, off + 2)[0]
    size = struct.unpack_from("<I", data, off + 10)[0]
    flags = data[off + 25]
    fi_len = data[off + 32]
    fi = data[off + 33:off + 33 + fi_len]
    su_start = off + 33 + fi_len
    if (33 + fi_len) % 2 == 1:
        su_start += 1
    su = data[su_start:off + dr_len] if off + dr_len > su_start else b""
    return dict(dr_len=dr_len, lba=lba, size=size, flags=flags, fi=fi, su=su)

def rr_fields(su):
    # returns (name, is_symlink, sl_target)
    name = b""
    is_sl = False
    sl = b""
    i = 0
    while i + 3 < len(su):
        sig = su[i:i + 2]
        ln = su[i + 2]
        if ln == 0:
            break
        if sig == b"NM":
            name += su[i + 5:i + ln]
        elif sig == b"SL":
            is_sl = True
            # SL: bytes[5] flags, then components
            comp = su[i + 5:i + ln]
            j = 0
            while j + 2 <= len(comp):
                cflags = comp[j]
                clen = comp[j + 1]
                cdata = comp[j + 2:j + 2 + clen]
                if cflags & 0x02:
                    sl += b"."
                elif cflags & 0x04:
                    sl += b"/"
                elif cflags & 0x08:
                    sl += b"/"
                else:
                    sl += cdata
                j += 2 + clen
                if not (cflags & 0x01):
                    sl += b"/"
        i += ln
    return name, is_sl, sl

# find PVD
pvd = None
for sec in range(16, 32):
    d = read_at(sec * SECTOR, SECTOR)
    if d[0] == 1 and d[1:6] == b"CD001":
        pvd = d
        break
if not pvd:
    print("No PVD found")
    sys.exit(1)
print("PVD found. Volume ID:", pvd[40:72].decode("utf-8", "replace").strip())

root = parse_dr(pvd, 156)

def walk(lba, size, depth):
    data = read_at(lba * SECTOR, size)
    off = 0
    while off < len(data):
        rec = parse_dr(data, off)
        if rec is None:
            nxt = ((off // SECTOR) + 1) * SECTOR
            if nxt <= off:
                break
            off = nxt
            continue
        if rec["fi"] in (b"\x00", b"\x01"):
            off += rec["dr_len"]
            continue
        nm, is_sl, slt = rr_fields(rec["su"])
        if nm:
            disp = nm.decode("utf-8", "replace")
        else:
            disp = rec["fi"].split(b";")[0].decode("utf-8", "replace")
        is_dir = bool(rec["flags"] & 0x02)
        kind = "DIR " if is_dir else "FILE"
        extra = ""
        if is_sl:
            extra = " -> SLINK '%s'" % slt.decode("utf-8", "replace")
        print("%s%-32s lba=%-8d size=%-10d%s" % ("  " * depth + kind, disp, rec["lba"], rec["size"], extra))
        if is_dir and not is_sl:
            walk(rec["lba"], rec["size"], depth + 1)
        off += rec["dr_len"]

walk(root["lba"], root["size"], 0)

